// Agreement attachments are backups; upload success never depends on parsing.

agreementUpload=function(id){
const d=extraDialog(`<div class="dialogtop"><h2>文档类型资料附件备份</h2><button data-close>✕</button></div><label>关联文档类型资料<select data-agreement><option value="">请选择已保存的文档</option>${S.data.technical_agreements.map(a=>`<option value="${a.id}" ${a.id===id?'selected':''}>${esc(a.code)} · ${esc(a.name)}</option>`).join('')}</select></label><div class="uploadbox" data-drop><p>拖拽文件到这里，或选择本地文件 / 文件夹</p><button type="button" data-pick>选择文件</button><button type="button" data-folder-pick>选择文件夹</button><input type="file" data-files multiple hidden><input type="file" data-folder webkitdirectory multiple hidden></div><p>单文件最多 256 MB。文件夹中的文件分别备份，不保留目录层级。不会覆盖同名文件。</p><p data-message role="status"></p><div data-backups></div>`);
const select=d.querySelector('[data-agreement]'),message=d.querySelector('[data-message]');let busy=false;
const update=()=>{d.querySelector('[data-backups]').innerHTML=select.value?agreementFileLinks(Number(select.value)):''};select.onchange=update;update();
async function upload(files){if(busy)return;if(!select.value){message.textContent='请先选择协议；没有协议时，请关闭窗口并新增保存协议。';return}if(!files.length){message.textContent='没有选择文件';return}busy=true;select.disabled=true;d.querySelectorAll('button:not([data-close])').forEach(b=>b.disabled=true);let count=0;const failures=[];try{for(const file of files){try{if(file.size>256*1024*1024)throw Error('超过 256 MB');message.textContent='正在上传 '+file.name;const q=new URLSearchParams({kind:'agreement',agreement_id:select.value,name:file.name});const r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:file});let j;try{j=await r.json()}catch{throw Error('服务器返回异常，请检查服务日志')}if(!r.ok)throw Error(j.error||'上传失败');count++}catch(e){failures.push(file.name+'：'+e.message)}}S=await request('/api/state');update();message.textContent=`成功备份 ${count} 个文件。`+(failures.length?'失败：'+failures.join('；'):'可在下方下载核对。')}catch(e){message.textContent=`已上传 ${count} 个文件，刷新列表失败：${e.message}`}finally{busy=false;select.disabled=false;d.querySelectorAll('button').forEach(b=>b.disabled=false)}}
for(const [button,input] of [['[data-pick]','[data-files]'],['[data-folder-pick]','[data-folder]']]){const field=d.querySelector(input);d.querySelector(button).onclick=()=>field.click();field.onchange=()=>{upload(Array.from(field.files));field.value=''}}
const drop=d.querySelector('[data-drop]');drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();upload(Array.from(e.dataTransfer.files))};d.addEventListener('close',()=>refresh(),{once:true});
};

function imagePriority(a,b){if(imagePriority.rows!==S.data.image_defects){imagePriority.rows=S.data.image_defects;imagePriority.assigned=new Set(S.data.image_defects.map(d=>d.image_id))}const assigned=imagePriority.assigned;return Number(assigned.has(a.id))-Number(assigned.has(b.id))||b.id-a.id}
function imageDefectsDialog(imageIds=[]){const d=extraDialog(`<form><div class="dialogtop"><h2>批量绑定图片缺陷</h2><button type="button" data-close>✕</button></div>${imageIds.length?`<p>为选中的 ${imageIds.length} 张图片绑定以下缺陷。</p>`:`<label>图片<select name="image_id" required><option value="">请选择图片（未绑缺陷、最新录入优先）</option>${[...S.data.images].sort(imagePriority).map(i=>`<option value="${i.id}">${esc(label('images',i.id))}</option>`).join('')}</select></label>`}<p>可一次勾选多个缺陷；已有绑定保留，不重复新增。</p>${S.data.defect_types.map(x=>`<label style="display:block"><input type="checkbox" name="defect_ids" value="${x.id}"> ${esc(x.name)}</label>`).join('')||'<p>请先新增缺陷字典。</p>'}<label>确认说明<input name="remark" maxlength="1024"></label><p class="error"></p><button type="button" data-close>取消</button><button class="primary" type="submit">保存全部缺陷绑定</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const f=new FormData(e.target),result=await request('/api/image-defects',{image_ids:imageIds.length?imageIds:[Number(f.get('image_id'))],defect_ids:f.getAll('defect_ids').map(Number),remark:f.get('remark')});d.close();await refresh();toast(`已新增 ${result.count} 条缺陷绑定，已有绑定不重复写入`)}catch(e){d.querySelector('.error').textContent=e.message}finally{button.disabled=false}}}
const editWithMultiDefects=edit;edit=function(id){if(table==='image_defects'&&!id){imageDefectsDialog();return}editWithMultiDefects(id);if(table==='technical_agreements'){const oldReading=$('#fields [name=extracted_text]')?.closest('label');if(oldReading)oldReading.hidden=true}};
const galleryWithDefects=drawGallery;drawGallery=function(){galleryWithDefects();let batch=$('#batch-image-defects');if(!batch){batch=document.createElement('button');batch.id='batch-image-defects';batch.textContent='批量绑定缺陷';batch.onclick=()=>{if(!selectedImages.size){toast('请先勾选图片');return}imageDefectsDialog([...selectedImages])};$('#bindselected').before(batch)}batch.disabled=!S.auth;$('#imagecount').textContent+=' · 未绑定缺陷优先，同组最新录入优先';$('#imagecards').querySelectorAll('[data-onebind]').forEach(b=>{const id=Number(b.dataset.onebind),button=document.createElement('button');button.textContent='绑定多个缺陷';button.disabled=!S.auth;button.onclick=()=>imageDefectsDialog([id]);b.after(button);const note=document.createElement('p'),defects=S.data.image_defects.filter(x=>x.image_id===id);note.textContent=defects.length?'缺陷：'+defects.map(x=>label('defect_types',x.defect_type_id)).join('、'):'未绑定缺陷';b.closest('article').append(note)})};

// Dedicated engineering editor makes the image count explicit and avoids hidden required asset fields.
function editEngineering(id){rememberRevision('engineering_projects',id);const row=S.data.engineering_projects.find(e=>e.id===id);if(!row)return;const d=extraDialog(`<form><div class="dialogtop"><h2>编辑检测工程</h2><button type="button" data-close>✕</button></div><label>工程名称<input name="name" value="${esc(row.name)}" required></label><label>工程图片数量<input name="image_count" type="number" min="0" step="1" value="${row.image_count??''}" placeholder="填写当前工程图片总数，0 表示没有图片"></label><label>工程版本<input name="engineering_version" value="${esc(row.engineering_version)}"></label><label>本地工程路径<input name="local_path" value="${esc(row.local_path)}"></label><label>备注<textarea name="remark">${esc(row.remark)}</textarea></label><p class="error"></p><button class="primary" type="submit">保存工程</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const record={...row,...Object.fromEntries(new FormData(e.target))};await request('/api/save',{table:'engineering_projects',id,record});d.close();await refresh();toast('工程图片数量已更新')}catch(e){d.querySelector('.error').textContent=e.message}}}
const editWithEngineeringCount=edit;edit=function(id){if(table==='engineering_projects'&&id){editEngineering(id);return}editWithEngineeringCount(id)};
