function modelTestEditor(id){rememberRevision('model_tests',id);const row=S.data.model_tests.find(r=>r.id===id)||{},fields=[['name','测试名称 *'],['model_name','模型 / 软件 / 算法名称 *'],['model_version','模型 / 软件版本'],['test_date','测试日期'],['light_source','光源类型'],['camera','相机型号'],['lens','镜头型号']];const d=extraDialog(`<form><div class="dialogtop"><h2>${id?'编辑':'新增'}软件测试记录</h2><button type="button" data-close>✕</button></div><div class="aligned-fields"><label>测试模块 *<input name="test_module" list="test-module-options" required maxlength="191" value="${esc(row.test_module||'大模型测试')}"><datalist id="test-module-options">${testModules().map(m=>`<option value="${esc(m)}"></option>`).join('')}</datalist></label>${fields.map(([name,label])=>`<label>${label}<input name="${name}" value="${esc(row[name])}" ${['name','model_name'].includes(name)?'required':''} ${name==='test_date'?'type="date"':''}></label>`).join('')}<label>关联产品<select name="product_id"><option value="">暂不关联</option>${S.data.products.map(p=>`<option value="${p.id}" ${p.id===row.product_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>工作距离（mm）<input name="working_distance_mm" type="number" min="0" step="any" value="${row.working_distance_mm??''}" placeholder="例如 120.5"></label><label>产品规格<textarea name="product_spec" maxlength="1024">${esc(row.product_spec)}</textarea></label><label>测试产品总数<input name="test_count" type="number" min="0" step="1" value="${row.test_count??''}"></label><label>检出率（%）<input name="detection_rate" type="number" min="0" max="100" step="any" value="${row.detection_rate??''}" placeholder="例如 98.5"></label><label>良率（%）<input name="yield_rate" type="number" min="0" max="100" step="any" value="${row.yield_rate??''}" placeholder="例如 1.5"></label><label>测试环境备注<textarea name="prompt" maxlength="1024">${esc(row.prompt)}</textarea></label><label>效果说明<textarea name="remark" maxlength="1024">${esc(row.remark)}</textarea></label>${['test_method','expected_result','actual_result'].map((name,i)=>`<label class="field-wide">${['测试方法与步骤','预期结果','实际结果与测量数据'][i]}<textarea name="${name}" maxlength="20000">${esc(row[name])}</textarea></label>`).join('')}</div>${knowledgeFields('model_tests',id,row)}<p>按测试模块填写相关指标，其余可留空。先保存记录，再上传测试原图和效果图。</p><p class="error"></p><button class="primary">保存测试记录</button></form>`);wireKnowledgeForm(d,'model_tests',id);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const j=await saveKnowledgeForm(e.target,'model_tests',id);d.close();await refresh();if(!id)modelTestUpload(j.id)}catch(e){d.querySelector('.error').textContent=e.message}}}
function testModules(){return [...new Set(['大模型测试','AI检测稳定性测试','AI运行时间测试','算法重复误差测试',...(S.data.model_tests||[]).map(r=>r.test_module).filter(Boolean)])]}
function modeltests(){const records=[...S.data.model_tests].sort((a,b)=>b.id-a.id);$('#content').innerHTML=title('SOFTWARE TEST LOG','软件测试记录','按模块管理测试方法、测量数据与效果图；支持自定义测试模块。',S.auth?'<button class="primary" id="new-model-test">＋ 新增测试记录</button>':'<span class="pill">只读浏览</span>')+'<button id="offline-shortcut">进入大模型离线测试 →</button><label class="module-filter">测试模块<select id="test-module-filter"><option value="">全部模块</option>'+testModules().map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('')+'</select></label><input id="model-test-filter" class="search" placeholder="搜索测试名称、模型、产品、相机、光源、规格…"><div id="model-test-list"></div>';$('#offline-shortcut').onclick=()=>go('offline');$('#new-model-test')?.addEventListener('click',()=>modelTestEditor());const draw=()=>{const q=$('#model-test-filter').value.trim().toLowerCase(),all=records.filter(r=>(!$('#test-module-filter').value||(r.test_module||'大模型测试')===$('#test-module-filter').value)&&[r.test_module,r.test_method,r.expected_result,r.actual_result,r.name,r.model_name,r.model_version,r.remark,r.prompt,r.light_source,r.camera,r.lens,r.product_spec,r.working_distance_mm,label('products',r.product_id)].join(' ').toLowerCase().includes(q));$('#model-test-list').innerHTML=all.map(r=>{const files=S.data.model_test_files.filter(f=>f.test_id===r.id);return `<section class="panel model-test-panel"><div class="panelhead"><h2>${esc(r.name)}</h2><span class="pill">${esc(r.test_module||'大模型测试')}</span><span class="pill">${r.test_count??'待填'} 个测试产品</span></div><p>模型 / 软件 / 算法：${esc(r.model_name)} ${esc(r.model_version)} · ${esc(r.test_date||'未填写日期')} · 产品：${esc(r.product_id?label('products',r.product_id):'未关联')}</p><div class="model-hardware"><p>光源类型：${esc(r.light_source||'未填写')} · 相机：${esc(r.camera||'未填写')} · 镜头：${esc(r.lens||'未填写')}</p><p>工作距离：${r.working_distance_mm==null?'未填写':esc(r.working_distance_mm)+' mm'}</p><p class="model-test-note">产品规格：${esc(r.product_spec||'未填写')}</p></div><p>检出率：${r.detection_rate==null?'待填写':esc(r.detection_rate)+'%'} · 良率：${r.yield_rate==null?'待填写':esc(r.yield_rate)+'%'}</p><p class="subtle">录入作者：${esc(r.created_by||'历史记录未登记')} · ${esc(r.created_at||'')}</p><p class="model-test-note">${esc(r.remark||'尚未填写效果说明')}</p><details><summary>测试环境备注</summary><p class="model-test-note">${esc(r.prompt||'未填写')}</p></details>${['test_method','expected_result','actual_result'].map((key,i)=>r[key]?`<h3>${['测试方法与步骤','预期结果','实际结果与测量数据'][i]}</h3><p class="model-test-note">${esc(r[key])}</p>`:'').join('')}${['input','result'].map(role=>`<h3>${role==='input'?'测试原图':'检测效果图'}</h3><div class="model-test-gallery">${files.filter(f=>f.role===role).map(f=>{const asset=S.data.assets.find(a=>a.id===f.asset_id);return `<figure><button type="button" class="model-preview-button" data-model-preview="${f.asset_id}"><img loading="lazy" src="/api/media?id=${f.asset_id}&mode=thumb" alt="${esc(asset?.file_name)}"></button><figcaption>${esc(asset?.file_name)}<small class="subtle"> 上传作者：${esc(asset?.created_by||'历史记录未登记')}</small> <a href="/api/media?id=${f.asset_id}&mode=original">下载原图</a>${S.auth?` <button data-model-file-rename="${f.id}">重命名</button>`:''}${S.auth?.role==='admin'?` <button class="danger" data-model-file-delete="${f.id}">删除图片</button>`:''}</figcaption></figure>`}).join('')||'<p class="muted">暂无图片</p>'}</div>`).join('')}<div class="toolbar">${S.auth?`<button data-model-edit="${r.id}">编辑记录</button><button data-model-upload="${r.id}">上传 / 粘贴图片</button>`:''}${S.auth?.role==='admin'?`<button class="danger" data-model-delete="${r.id}">删除测试记录</button>`:''}</div></section>`}).join('')||'<div class="empty">暂无测试记录</div>';$('#model-test-list').querySelectorAll('[data-model-file-rename]').forEach(b=>b.onclick=()=>renameModelTestImage(Number(b.dataset.modelFileRename)));$('#model-test-list').querySelectorAll('[data-model-file-delete]').forEach(b=>b.onclick=()=>deleteModelTestImage(Number(b.dataset.modelFileDelete)));$('#model-test-list').querySelectorAll('[data-model-preview]').forEach(b=>b.onclick=()=>modelImagePreview(Number(b.dataset.modelPreview)));$('#model-test-list').querySelectorAll('[data-model-edit]').forEach(b=>b.onclick=()=>modelTestEditor(Number(b.dataset.modelEdit)));$('#model-test-list').querySelectorAll('[data-model-upload]').forEach(b=>b.onclick=()=>modelTestUpload(Number(b.dataset.modelUpload)));$('#model-test-list').querySelectorAll('[data-model-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('删除测试记录及其图片关联？原文件保留在备份目录中。'))return;try{await request('/api/model-test-delete',{id:Number(b.dataset.modelDelete)});await refresh()}catch(e){toast(e.message)}})};$('#model-test-filter').oninput=draw;$('#test-module-filter').onchange=draw;draw()}
function modelTestUpload(id){const d=extraDialog(`<div class="dialogtop"><h2>添加测试图片</h2><button data-close>✕</button></div><label>图片用途<select data-role><option value="input">测试原图</option><option value="result">检测效果图</option></select></label><div class="uploadbox" tabindex="0" data-test-drop><p>选择或拖拽图片，也可在此窗口按 Ctrl+V 粘贴截图</p><input data-test-files type="file" accept="image/png,image/jpeg,image/bmp,image/tiff,image/webp" multiple></div><p data-test-status role="status"></p>`);let busy=false;async function upload(files){if(busy||!files.length)return;busy=true;const role=d.querySelector('[data-role]').value,status=d.querySelector('[data-test-status]');d.querySelector('[data-role]').disabled=true;let count=0;try{for(const file of files){if(file.size>256*1024*1024)throw Error(file.name+' 超过 256 MB');const q=new URLSearchParams({kind:'modeltest',test_id:id,role,name:file.name||'clipboard.png'}),r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:file}),j=await r.json();if(!r.ok)throw Error(j.error);count++}status.textContent=`成功保存 ${count} 张${role==='input'?'测试原图':'效果图'}，可切换用途继续添加。`;S=await request('/api/state')}catch(e){status.textContent=`已保存 ${count} 张；${e.message}`}finally{busy=false;d.querySelector('[data-role]').disabled=false}}d.querySelector('[data-test-files]').onchange=e=>{upload(Array.from(e.target.files));e.target.value=''};const zone=d.querySelector('[data-test-drop]');zone.ondragover=e=>e.preventDefault();zone.ondrop=e=>{e.preventDefault();upload(Array.from(e.dataTransfer.files))};d.addEventListener('paste',e=>{const files=Array.from(e.clipboardData.items).filter(i=>i.type.startsWith('image/')).map(i=>i.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();upload(files)}});d.addEventListener('close',()=>refresh(),{once:true})}

function modelImagePreview(assetId){const asset=S.data.assets.find(a=>a.id===assetId);if(!asset)return;const d=extraDialog(`<div class="dialogtop"><h2>${esc(asset.file_name)}</h2><button data-close>✕</button></div><div class="toolbar"><button data-fit>适应窗口</button><button data-full>原始尺寸</button><a href="/api/media?id=${assetId}&mode=original">下载原文件</a></div><div class="originalviewport"><img src="/api/media?id=${assetId}&mode=view" alt="${esc(asset.file_name)}"><p data-image-error hidden>图片不可用，请检查原文件。</p></div>`,'viewer');const image=d.querySelector('img');d.querySelector('[data-full]').onclick=()=>image.classList.add('actualpixels');d.querySelector('[data-fit]').onclick=()=>image.classList.remove('actualpixels');image.onerror=()=>{image.hidden=true;d.querySelector('[data-image-error]').hidden=false}}

videoUpload=function(imageId){if(!S.data.projects.length){toast('请先登记项目，再上传视频');return}const image=S.data.images.find(i=>i.id===imageId),links=image?S.data.project_assets.filter(p=>p.asset_id===image.asset_id):[],project=links.length===1?links[0].project_id:null;const d=extraDialog(`<form><div class="dialogtop"><h2>上传视频资料</h2><button type="button" data-close>✕</button></div><label>绑定项目<select name="project_id" required><option value="">请选择项目</option>${S.data.projects.map(p=>`<option value="${p.id}" ${p.id===project?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>视频名称<input name="title" required maxlength="191"></label><label>本地视频<input type="file" name="file" accept=".mp4,.webm,.mov,.avi,.mkv,.m4v" required></label><p>视频直接关联项目，单文件最多 1 GB。</p><p class="error"></p><button type="submit" class="primary">上传并保存视频</button></form>`);const f=d.querySelector('form');f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;try{const file=f.elements.file.files[0];if(file.size>1024**3)throw Error('视频超过 1 GB');const q=new URLSearchParams({kind:'video',project_id:f.elements.project_id.value,title:f.elements.title.value,name:file.name}),r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:file}),j=await r.json();if(!r.ok)throw Error(j.error);d.close();await refresh();toast('视频已保存并绑定项目')}catch(e){d.querySelector('.error').textContent=e.message}finally{button.disabled=false}}};
function agreementRecordEditor(id){rememberRevision('technical_agreements',id);const row=S.data.technical_agreements.find(a=>a.id===id)||{};const d=extraDialog(`<form><div class="dialogtop"><h2>${id?'编辑':'新增'}文档类型资料</h2><button type="button" data-close>✕</button></div><label>项目<select name="project_id"><option value="">通用文档 / 不绑定项目</option>${S.data.projects.map(p=>`<option value="${p.id}" ${row.project_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>文档类型<select name="document_type" required>${documentTypeOptions(row.document_type||'技术协议')}</select></label><button type="button" data-new-document-type>＋ 新增文档类别</button><label>文档编号<input name="code" required maxlength="191" value="${esc(row.code)}"></label><label>文档名称<input name="name" required maxlength="191" value="${esc(row.name)}"></label><label>文档日期<input name="signed_date" type="date" value="${esc(row.signed_date)}"></label><label>文档说明<textarea name="requirements" maxlength="1024">${esc(row.requirements)}</textarea></label><label>备注<textarea name="remark" maxlength="1024">${esc(row.remark)}</textarea></label><label>${id?'追加文档附件（可选）':'上传本地文档类型资料文件'}<input type="file" data-agreement-file ${id?'':'required'}></label><p>原文件直接备份到工程数据目录，最多 256 MB；不解析文档。</p>${id?agreementFileLinks(id):''}<p class="error"></p><button class="primary" type="submit">${id?'保存修改':'上传并保存文档记录'}</button></form>`);const f=d.querySelector('form');d.querySelector('[data-new-document-type]').onclick=()=>newDocumentType(f.elements.document_type);f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;let metadataSaved=false;try{const record={...row,...Object.fromEntries(new FormData(f))},file=f.querySelector('[data-agreement-file]').files[0];if(file&&file.size>256*1024*1024)throw Error('文档附件不能超过 256 MB');if(id){await request('/api/save',{table:'technical_agreements',id,record});metadataSaved=true;if(file){const q=new URLSearchParams({kind:'agreement',agreement_id:id,name:file.name}),r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:file}),j=await r.json();if(!r.ok)throw Error(j.error)}}else{if(!file)throw Error('请选择文档类型资料文件');const q=new URLSearchParams({kind:'agreement_new',name:file.name,record:JSON.stringify(record)}),r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:file}),j=await r.json();if(!r.ok)throw Error(j.error)}d.close();await refresh();toast('文档类型资料记录与附件已保存')}catch(e){f.querySelector('.error').textContent=(metadataSaved?'信息已保存，附件上传失败：':'')+e.message}finally{button.disabled=false}}}
const editWithAgreementFile=edit;edit=function(id){if(table==='technical_experiences'){technicalExperienceEditor(id);return}if(table==='model_tests'){modelTestEditor(id);return}if(table==='technical_agreements'){agreementRecordEditor(id);return}editWithAgreementFile(id);if(table==='videos'&&id){const project=$('#fields [name=project_id]');if(project)project.required=!S.data.videos.find(v=>v.id===id)?.asset_id}};

function renameModelTestImage(fileId){const item=S.data.model_test_files.find(f=>f.id===fileId),asset=S.data.assets.find(a=>a.id===item?.asset_id);if(!asset)return;const suffix=asset.file_name.match(/\.[^.]+$/)?.[0]||'',d=extraDialog(`<form><div class="dialogtop"><h2>重命名测试图片</h2><button type="button" data-close>✕</button></div><label>图片名称<input name="stem" value="${esc(asset.file_name.slice(0,suffix? -suffix.length:undefined))}" required maxlength="180"></label><p>后缀 ${esc(suffix)} 自动保留；原图内容、测试记录及图片用途不变。</p><p class="error"></p><button class="primary" type="submit">保存名称</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await request('/api/model-test-file-rename',{file_id:fileId,stem:e.target.elements.stem.value});d.close();await refresh();toast('测试图片已重命名')}catch(e){d.querySelector('.error').textContent=e.message}finally{button.disabled=false}}}
async function deleteModelTestImage(fileId){if(!confirm('删除这张测试图片？测试记录和其他图片会保留，原文件移入数据目录回收区。'))return;try{await request('/api/model-test-file-delete',{file_id:fileId});await refresh();toast('测试图片已删除')}catch(e){toast(e.message)}}

const accountsWithBatch=accounts;accounts=async function(){await accountsWithBatch();if(S.auth?.role!=='admin')return;const button=document.createElement('button');button.textContent='批量创建 50 个录入账号并下载密码清单';$('#content').prepend(button);button.onclick=async()=>{if(!confirm('创建 50 个独立密码的录入员账号？密码清单仅此次下载，请妥善保管并分别交给对应人员。'))return;button.disabled=true;try{const result=await request('/api/auth/users-batch',{count:50,prefix:'member'});download('new-accounts.csv','\ufeff账号,初始密码,角色\r\n'+result.accounts.map(a=>[a.username,a.password,a.role].join(',')).join('\r\n'),'text/csv;charset=utf-8');await accounts();toast('已创建 50 个账号；密码清单请安全保管')}catch(e){toast(e.message)}finally{button.disabled=false}}};

