'use strict';

// Queue state survives page switches; only polling and rendering stop when the page is hidden.
pages.offline=['◉','大模型离线测试'];
const offlineUI={epoch:0,timer:null,activeId:null,uploading:false,files:[],models:[],modelError:'',job:null,polling:false};
const offlineTerminal=new Set(['completed','completed_with_errors','failed','cancelled','interrupted']);
const offlineStatus={uploading:'等待上传完成',uploaded:'已上传，等待提交',queued:'排队等待',running:'正在预测',completed:'已完成',completed_with_errors:'完成，部分图片失败',failed:'失败',cancelled:'已取消',interrupted:'服务重启，任务已中断'};
function offlineVisible(){return page==='offline'&&!!document.querySelector('#offline-root')}
function offlineMessage(text,error=false){const node=document.querySelector('#offline-message');if(node){node.textContent=text;node.classList.toggle('offline-error',error)}}
function offlineNumber(value,digits=4){const n=Number(value);return Number.isFinite(n)?n.toFixed(digits):'—'}
function offlineFileURL(jobId,itemId,kind,version=''){return '/api/offline/file?'+new URLSearchParams({job_id:jobId,item_id:itemId,kind,...(version?{v:version}:{})})}
function offlineParams(form){
 const values=new FormData(form),params={};
 for(const key of ['seg_threshold','min_area','alpha','smooth_sigma']){const n=Number(values.get(key));if(!Number.isFinite(n))throw Error('请填写有效的分割参数');params[key]=n}
 const raw=String(values.get('image_threshold')||'').trim();params.image_threshold=raw===''?null:Number(raw);
 if(params.seg_threshold<0||params.min_area<1||!Number.isInteger(params.min_area)||params.alpha<0||params.alpha>1||params.smooth_sigma<0||params.smooth_sigma>10||(params.image_threshold!==null&&(!Number.isFinite(params.image_threshold)||params.image_threshold<0)))throw Error('分割阈值须非负，最小面积须为正整数，透明度须在 0–1 之间，平滑参数须在 0–10 之间');
 return params;
}
